def rec_bin_search(arr, ele):

    # Base Case!
    if len(arr) == 0:
        return False

    # Recursive Case
    else:
        mid = len(arr) // 2

        # If match found
        if arr[mid] == ele:
            return True

        else:
            # Call again on second half
            if ele &lt; arr[mid]:
                return rec_bin_search(arr[:mid], ele)

            # Or call on first half
            else:
                return rec_bin_search(arr[mid + 1 :], ele)


